/**
 * Checks the identity management operations requested through the Identity REST APIs against the permissions of the
 * caller. A non admin caller can only manage identities whose permissions are a subset of its own and can only assign
 * permissions that it holds. Permission creation and deletion is reserved to kura.admin. The additional
 * configurations of an identity are returned to a non admin caller only if the caller can manage that identity.
 * Requests received through a RequestHandler (e.g. MQTT) have no request context and are considered trusted.
 * The checks can be disabled, restoring the behaviour of the previous releases, by adding the
 * -kura.rest.identity.legacyIdentityManagement argument to the Java command line in the Kura startup script.
 * If the IdentityService is not available, the requests performed by an identity are rejected.
 */
class IdentityAccessGuard {

    private static final Logger logger = LoggerFactory.getLogger(IdentityAccessGuard.class);

    private static final String LEGACY_IDENTITY_MANAGEMENT_ARGUMENT = "-kura.rest.identity.legacyIdentityManagement";

    private static final String ADMIN_PERMISSION = "kura.admin";

    private static final Permission ADMIN = new Permission(ADMIN_PERMISSION);

    private final Supplier<IdentityService> identityService;
    private final BooleanSupplier legacyIdentityManagement;

    IdentityAccessGuard(final Supplier<IdentityService> identityService,
            final BooleanSupplier legacyIdentityManagement) {
        this.identityService = identityService;
        this.legacyIdentityManagement = legacyIdentityManagement;
    }

    static boolean isLegacyIdentityManagementEnabled(final EnvironmentInfo environmentInfo) {
        final String[] arguments = environmentInfo.getNonFrameworkArgs();
        final boolean enabled = arguments != null
                && Arrays.asList(arguments).contains(LEGACY_IDENTITY_MANAGEMENT_ARGUMENT);

        if (enabled) {
            logger.warn("{} is set: identity management requests are not checked against the caller permissions",
                    LEGACY_IDENTITY_MANAGEMENT_ARGUMENT);
        }

        return enabled;
    }

    void requireAdmin(final ContainerRequestContext requestContext, final String operation) {
        final Optional<String> caller = getCaller(requestContext);

        if (caller.isPresent() && !isAllowed(() -> isAdmin(caller.get()))) {
            throw forbidden(caller.get(), operation);
        }
    }

    boolean canManageIdentity(final ContainerRequestContext requestContext, final String identityName) {
        final Optional<String> caller = getCaller(requestContext);

        return !caller.isPresent() || isAllowed(
                () -> isAdmin(caller.get()) || permissionsOf(caller.get()).containsAll(permissionsOf(identityName)));
    }

    void requireCanManageIdentity(final ContainerRequestContext requestContext, final String identityName) {
        if (!canManageIdentity(requestContext, identityName)) {
            throw forbidden(getCaller(requestContext).orElse(null), "manage identity " + identityName);
        }
    }

    void requireCanAssignPermissions(final ContainerRequestContext requestContext,
            final Collection<String> permissions) {
        final Optional<String> caller = getCaller(requestContext);

        if (caller.isPresent()
                && !isAllowed(() -> isAdmin(caller.get()) || permissionsOf(caller.get()).containsAll(permissions))) {
            throw forbidden(caller.get(), "assign permissions " + permissions);
        }
    }

    /*
     * Evaluates an access check, denying access if the IdentityService is not available or a lookup fails.
     */
    private static boolean isAllowed(final AccessCheck check) {
        try {
            return check.evaluate();
        } catch (final KuraException e) {
            logger.warn("Unable to verify the permissions of the requesting identity", e);
            return false;
        }
    }

    private boolean isAdmin(final String identityName) throws KuraException {
        final IdentityService service = requireIdentityService();

        try {
            service.checkPermission(identityName, ADMIN);
            return true;
        } catch (final KuraException e) {
            return false;
        }
    }

    private Set<String> permissionsOf(final String identityName) throws KuraException {
        return requireIdentityService()
                .getIdentityConfiguration(identityName, Collections.singleton(AssignedPermissions.class))
                .flatMap(identity -> identity.getComponent(AssignedPermissions.class))
                .map(assigned -> assigned.getPermissions().stream().map(Permission::getName)
                        .collect(Collectors.toSet()))
                .orElseGet(Collections::emptySet);
    }

    private IdentityService requireIdentityService() throws KuraException {
        final IdentityService service = this.identityService.get();

        if (service == null) {
            throw new KuraException(KuraErrorCode.SERVICE_UNAVAILABLE, "IdentityService not available");
        }

        return service;
    }

    private Optional<String> getCaller(final ContainerRequestContext requestContext) {
        if (requestContext == null || this.legacyIdentityManagement.getAsBoolean()) {
            return Optional.empty();
        }

        final Optional<String> caller = Optional.ofNullable(requestContext.getSecurityContext())
                .map(c -> c.getUserPrincipal()).map(Principal::getName);

        if (!caller.isPresent()) {
            throw new WebApplicationException(Status.UNAUTHORIZED);
        }

        return caller;
    }

    private static WebApplicationException forbidden(final String caller, final String operation) {
        logger.warn("Identity {} is not allowed to {}", caller, operation);
        return DefaultExceptionHandler.buildWebApplicationException(Status.FORBIDDEN,
                "The requesting identity is not allowed to perform this operation");
    }

    @FunctionalInterface
    private interface AccessCheck {

        boolean evaluate() throws KuraException;
    }
}
